# First let's check if 26 edges, girth 6, on 14 vertices is even achievable
# Using bound: sum d(d-1) <= n(n-1) for girth >= 5
# For 26 edges: sum d = 52, min sum d^2 ~ 52^2/14 = 193.1, so sum d(d-1) >= 142 <= 182. OK.

# Try to construct via randomized search
import random
from itertools import combinations

def girth_at_least_6(adj, n):
    # BFS from each vertex, find shortest cycle
    for s in range(n):
        dist = {s: 0}
        parent = {s: -1}
        queue = [s]
        while queue:
            new_q = []
            for u in queue:
                for v in adj[u]:
                    if v not in dist:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        if dist[v] < 3:
                            new_q.append(v)
                    elif parent[u] != v:
                        # found cycle of length dist[u] + dist[v] + 1
                        cyc = dist[u] + dist[v] + 1
                        if cyc < 6:
                            return False
            queue = new_q
    return True

def has_short_cycle(adj, n):
    # Check no cycle of length < 6 through any edge
    # For each edge (u,v), check if there's a path of length <= 4 from u to v not using edge
    for u in range(n):
        for v in adj[u]:
            if v <= u: continue
            # BFS from u, avoiding edge uv
            dist = {u: 0}
            queue = [u]
            for _ in range(4):
                new_q = []
                for x in queue:
                    for y in adj[x]:
                        if x == u and y == v: continue
                        if x == v and y == u: continue
                        if y not in dist:
                            dist[y] = dist[x] + 1
                            new_q.append(y)
                queue = new_q
            if v in dist and dist[v] <= 4:
                return True
    return False

def check_girth6(edges, n):
    adj = [set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)
    return not has_short_cycle(adj, n)

# Try random construction
n = 14
best = 0
for trial in range(1000):
    random.seed(trial)
    all_edges = list(combinations(range(n), 2))
    random.shuffle(all_edges)
    adj = [set() for _ in range(n)]
    edges = []
    for u,v in all_edges:
        # try adding edge
        adj[u].add(v)
        adj[v].add(u)
        # check girth - BFS from u avoiding edge uv
        dist = {u: 0}
        queue = [u]
        found = False
        for _ in range(4):
            new_q = []
            for x in queue:
                for y in adj[x]:
                    if (x == u and y == v) or (x == v and y == u): continue
                    if y not in dist:
                        dist[y] = dist[x] + 1
                        new_q.append(y)
            queue = new_q
            if v in dist: 
                found = True
                break
        if found and dist[v] <= 4:
            adj[u].remove(v)
            adj[v].remove(u)
        else:
            edges.append((u,v))
    if len(edges) > best:
        best = len(edges)
        best_edges = edges
        print(f"trial {trial}: {len(edges)} edges")

print("Best:", best)
